import { useState } from 'react';
import { JxStepper, JxInputField, JxButton, JxTable } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_ROWS: Array<{ key: keyof RegistrationData; label: string }> = [
  { key: 'name', label: 'Имя' },
  { key: 'email', label: 'Почта' },
  { key: 'phone', label: 'Телефон' },
  { key: 'city', label: 'Город' },
  { key: 'street', label: 'Улица, дом' },
  { key: 'zip', label: 'Индекс' },
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const update = (key: keyof RegistrationData) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const { value } = event.target;
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const isLast = step === STEPS.length - 1;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      <JxStepper steps={STEPS} current={step} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {step === 0 && (
          <>
            <JxInputField label="Имя" required value={data.name} onChange={update('name')} />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              value={data.email}
              onChange={update('email')}
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              value={data.phone}
              onChange={update('phone')}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField label="Город" required value={data.city} onChange={update('city')} />
            <JxInputField label="Улица, дом" required value={data.street} onChange={update('street')} />
            <JxInputField
              label="Индекс"
              inputMode="numeric"
              helperText="Шесть цифр"
              value={data.zip}
              onChange={update('zip')}
            />
          </>
        )}

        {step === 2 && (
          <JxTable>
            <tbody>
              {REVIEW_ROWS.map((row) => (
                <tr key={row.key}>
                  <th scope="row" style={{ color: 'var(--jx-text-2)', textAlign: 'left' }}>
                    {row.label}
                  </th>
                  <td>{data[row.key] || '—'}</td>
                </tr>
              ))}
            </tbody>
          </JxTable>
        )}
      </div>

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {isLast ? (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

